void row_totals(int data[][COLS], int rows) {
    for (int r = 0; r < rows; r++) {
        int sum = 0;
        for (int c = 0; c < COLS; c++) sum += data[r][c];
        printf("row%d=%d\n", r, sum);
    }
}
void column_totals(int data[][COLS], int rows) {
    for (int c = 0; c < COLS; c++) {
