#include <stdio.h>
int sum_rows(int table[][3], int rows)
{
    int total = 0;
    for (int row = 0; row < rows; row++)
        for (int column = 0; column < 3; column++) total += table[row][column];
    return total;
}
int main(void)
{
    int table[2][3] = {{1, 2, 3}, {4, 5, 6}};
    printf("sum=%d\n", sum_rows(table, 2));
    return 0;
}

#include <stdio.h>
int sum_table(int rows, int columns, int table[rows][columns])
{
    int sum = 0;
    for (int row = 0; row < rows; row++)
        for (int column = 0; column < columns; column++) sum += table[row][column];
    return sum;
}
int main(void)
{
    int rows, columns;
    if (scanf("%d%d", &rows, &columns) != 2 || rows < 1 || rows > 3 || columns < 1 || columns > 3) return 1;
    int table[rows][columns];
    for (int row = 0; row < rows; row++)
        for (int column = 0; column < columns; column++) table[row][column] = 10 * row + column;
    printf("sum=%d\n", sum_table(rows, columns, table));
    return 0;
}

#include <stdio.h>
int sum(const int *values, int count)
{
    int total = 0;
    for (int i = 0; i < count; i++) total += values[i];
    return total;
}
int main(void)
{
    int total = sum((int[]){3, 4, 5}, 3);
    int *values = (int[3]){6, 7, 8};
    values[1] = 9;
    printf("total=%d changed=%d\n", total, values[1]);
    return 0;
}
